const fs=await import('node:fs');
const path=await import('node:path');
const assert=(await import('node:assert/strict')).default;
const {createRequire}=await import('node:module');
const cli='C:/Users/brand/.codex/worktrees/skill-cli-signals-20261002/apps/axi/dist/cli/index.js';
const require=createRequire(cli);
const yaml=require('js-yaml');
const runtime=await import('file:///C:/Users/brand/.codex/worktrees/skill-cli-signals-20261002/apps/axi/node_modules/@reactive-skills/runtime/dist/index.js');
const {FSMEngine,SkillManifestSchema,createReactiveBootloaderReference,createSortableId}=runtime;
const ws=process.cwd();
const skillDir=path.resolve('source-a/eval-report');
const manifest=SkillManifestSchema.parse(yaml.load(fs.readFileSync(path.join(skillDir,'skill.yaml'),'utf8')));
assert.equal(manifest.schema_version,'2.1.0');
assert.equal(manifest.initial_state,'INIT');
assert.deepEqual(Object.keys(manifest.states).sort(),['CANCELLED','DONE','INIT','WORK']);
assert.deepEqual(Object.keys(manifest.states.WORK.substates).sort(),['COLLECT','REVIEW']);
assert.equal(manifest.states.WORK.initial_substate,'COLLECT');
const expectedEdges=[
 ['INIT','RUNTIME_READY','WORK.COLLECT',''],
 ['WORK','CANCEL','CANCELLED',''],
 ['WORK.COLLECT','DATA_READY','WORK.REVIEW','payload.checks_passed === true'],
 ['WORK.REVIEW','HUMAN_APPROVED','DONE','']
].sort();
const edges=[];
const prompts=[];
function visit(states,prefix=''){
 for(const [name,state] of Object.entries(states)){
  const full=prefix?prefix+'.'+name:name;
  if(state.prompt_template)prompts.push(state.prompt_template);
  for(const [signal,t] of Object.entries(state.transitions||{}))edges.push([full,signal,t.target,t.guard||'']);
  if(state.substates)visit(state.substates,full);
 }
}
visit(manifest.states);
assert.deepEqual(edges.sort(),expectedEdges);
assert.deepEqual(prompts.sort(),['states/cancelled.md','states/done.md','states/init.md','states/work/collect.md','states/work/review.md']);
assert.deepEqual(manifest.default_context.red_discovery,{
 enabled:true,domain:'aggregate reports',unavailable_dependencies:'fail fast',
 data_policy:'no secrets or personal data',write_policy:'explicit approval before writes',
 audit_policy:'record state transitions',run_policy:'each run is isolated',
 coverage_policy:'record actual executor coverage separately from semantic model tiers'
});
assert.deepEqual(manifest.default_context.executor_coverage,[]);
const md=fs.readFileSync(path.join(skillDir,'SKILL.md'),'utf8').replace(/\\r\\n/g,'\\n');
const start='<"'!-- REACTIVE BOOTLOADER -->'"',end='<"'!-- END REACTIVE BOOTLOADER -->'"';
assert.equal(md.split(start).length,2);
assert.equal(md.split(end).length,2);
assert.equal(md.slice(md.indexOf(start),md.indexOf(end)+end.length).trim(),createReactiveBootloaderReference('eval-report').trim());
const diagram=fs.readFileSync(path.join(skillDir,'STATECHART.md'),'utf8').replace(/\\r\\n/g,'\\n');
const aliases={};
for(const line of diagram.split('\\n')){
 const parts=line.split(String.fromCharCode(34));
 if(parts.length===3&&parts[0].trim()==='state')aliases[parts[2].trim().split(/\\s+/)[1]]=parts[1];
}
assert.deepEqual(aliases,{WORK_COLLECT:'WORK.COLLECT',WORK_REVIEW:'WORK.REVIEW'});
const chartEdges=[];
for(const line of diagram.split('\\n')){
 const match=line.trim().match(/"'^('"\\w+) --> (\\w+) : (\\w+)(?: \\[(.*)\\])?/);
 if(match)chartEdges.push([aliases[match[1]]||match[1],match[3],aliases[match[2]]||match[2],match[4]||'']);
}
assert.deepEqual(chartEdges.sort(),expectedEdges);
assert.ok(diagram.includes('state WORK {'));
assert.ok(diagram.includes('[*] --> WORK_COLLECT'));
assert.ok(diagram.includes('[*] --> INIT'));
assert.ok(diagram.includes('DONE --> [*]'));
assert.ok(diagram.includes('CANCELLED --> [*]'));
const ready={
 transport:'axi',launcher:'direct',runtime_version:'0.16.0',axi_version:'0.16.0',
 compatible:true,capabilities:['runtime.bootloader','runtime.preflight','context.routing'],
 contextUpdates:{runtime:{transport:'axi',launcher:'direct',runtime_version:'0.16.0',compatible:true}}
};
