 return engine;
}
const metadata={source:'validation'};
const results={schema:true,canonical_bootloader:true,diagram_agreement:true,red_answers:7,transitions:[]};
const runIds=[];
try{
 let primary=open({jobId:'eval-report-validation-cli'});
