 runIds.push(primaryId);
 assert.equal(primary.getCurrentState(),'INIT');
 assert.ok(primary.generatePromptSlice().rawPrompt.startsWith('# eval-report: INIT'));
 const first=await primary.handleSignal('RUNTIME_READY',ready,metadata);
