 assert.equal(primary.getContext().runtime.runtime_version,'0.16.0');
 const rejectPayloads=[
  {contextUpdates:{checks_passed:true}},
  {checks_passed:false},{checks_passed:'true'},{checks_passed:1},{checks_passed:null}
 ];
