  const denied=await primary.handleSignal('DATA_READY',payload,metadata);
  assert.equal(denied.transitioned,false);
  assert.equal(primary.getCurrentState(),'WORK.COLLECT');
 }
 const premature=await primary.handleSignal('HUMAN_APPROVED',{validation_only:true},metadata);
 assert.equal(premature.transitioned,false);
 assert.equal(primary.getCurrentState(),'WORK.COLLECT');
 const accept=await primary.handleSignal('DATA_READY',{
  checks_passed:true,
  contextUpdates:{
   report:{summary:'Synthetic aggregate for runtime validation',cases:3,validation_only:true},
